class Digimon3DView(context: Context, initialDigimon: String = "Gabumon") : GLSurfaceView(context) {
    private val r=Renderer(initialDigimon); private var lastX=0f
    init{setEGLContextClientVersion(2);setRenderer(r);renderMode=RENDERMODE_CONTINUOUSLY}
    fun setDigimon(n:String){r.name=n}
    override fun onTouchEvent(e:MotionEvent):Boolean{when(e.actionMasked){MotionEvent.ACTION_DOWN->{lastX=e.x;return true};MotionEvent.ACTION_MOVE->{r.rotation+=(e.x-lastX)*.42f;lastX=e.x;return true}};return true}

    private class Renderer(var name:String):GLSurfaceView.Renderer{
        var rotation=0f;private val p=FloatArray(16);private val v=FloatArray(16);private val m=FloatArray(16);private val mv=FloatArray(16);private val nm=FloatArray(9);private val rot=FloatArray(16);private lateinit var mesh:Mesh;private var t0=System.nanoTime()
