        override fun onDrawFrame(g:GL10?){GLES20.glClear(GLES20.GL_COLOR_BUFFER_BIT or GLES20.GL_DEPTH_BUFFER_BIT);val t=(System.nanoTime()-t0)/1e9f;val bob=sin(t*2.1f)*.018f;val sway=sin(t*1.7f)*.035f;Matrix.setLookAtM(v,0,0f,1.55f,-7.5f,0f,1.42f,0f,0f,1f,0f);Matrix.setIdentityM(rot,0);Matrix.rotateM(rot,0,rotation,0f,1f,0f);when(name){"Gabumon"->gabumon(bob,sway);"Agumon"->agumon(bob,sway);"Patamon"->patamon(bob,sway);"Gatomon"->gatomon(bob,sway);"Tentomon"->tentomon(bob,sway);"Gomamon"->gomamon(bob,sway);"Palmon"->palmon(bob,sway);"Biyomon"->biyomon(bob,sway);"Veemon"->veemon(bob,sway);"Wormmon"->wormmon(bob,sway);"Guilmon"->guilmon(bob,sway);"Renamon"->renamon(bob,sway);else->gabumon(bob,sway)}}
        private fun base(b:Float,c:FloatArray,h:FloatArray,bel:FloatArray?=null){part(0f,1.03f+b,.02f,.82f,1f,.60f,c);part(0f,2.28f+b,-.02f,.68f,.68f,.57f,h);if(bel!=null)part(0f,1.04f+b,-.58f,.50f,.68f,.15f,bel);eye(-.23f,2.40f+b,h);eye(.23f,2.40f+b,h);arm(-.76f,1.12f+b,c);arm(.76f,1.12f+b,c);part(-.30f,.31f+b,0f,.28f,.55f,.28f,c);part(.30f,.31f+b,0f,.28f,.55f,.28f,c);part(-.34f,-.17f+b,-.34f,.36f,.18f,.43f,c);part(.34f,-.17f+b,-.34f,.36f,.18f,.43f,c)}
        private fun eye(x:Float,y:Float,h:FloatArray){part(x,y,-.61f,.105f,.14f,.055f,BLACK);part(x,y+.015f,-.665f,.052f,.08f,.014f,if(h===YELLOW)BLACK else RED);part(x+.018f,y+.045f,-.681f,.017f,.024f,.008f,WHITE)}
        private fun arm(x:Float,y:Float,c:FloatArray){part(x,y,-.02f,.23f,.55f,.23f,c);part(x,.64f,-.28f,.24f,.21f,.24f,c);claw(x-.09f,.60f,-.50f);claw(x+.09f,.60f,-.50f)}
        private fun claw(x:Float,y:Float,z:Float){part(x,y,z,.05f,.12f,.06f,CLAW)}
        private fun tail(x:Float,y:Float,z:Float,c:FloatArray,s:Float){part(x,y,z,.24f,.24f,.65f,c);part(x+.28f,y+.12f,z+.28f+s,.24f,.23f,.43f,c);part(x+.46f,y+.20f,z+.49f+s,.18f,.18f,.28f,c)}
        private fun ears(c:FloatArray,i:FloatArray,b:Float,w:Float=.52f){part(-w,2.78f+b,0f,.17f,.40f,.16f,c);part(w,2.78f+b,0f,.17f,.40f,.16f,c);part(-w,2.80f+b,-.15f,.08f,.25f,.05f,i);part(w,2.80f+b,-.15f,.08f,.25f,.05f,i)}
        private fun gabumon(b:Float,s:Float){base(b,BLUE,PELT,ORANGE);ears(BLUE,PINK,b);part(-.28f,2.15f+b,-.53f,.30f,.23f,.24f,MUZZLE);part(.28f,2.15f+b,-.53f,.30f,.23f,.24f,MUZZLE);part(0f,2.02f+b,-.79f,.11f,.05f,.03f,BLACK);part(0f,2.95f+b,-.01f,.13f,.32f,.12f,GOLD);part(0f,3.18f+b,-.01f,.07f,.17f,.07f,YELLOW);for(x in listOf(-.62f,.62f,-.75f,.75f))part(x,1.75f+b,.43f,.23f,.07f,.23f,STRIPE);tail(.92f,1.12f+b,.44f,BLUE,s)}
        private fun agumon(b:Float,s:Float){base(b,ORANGE,ORANGE,CREAM);part(-.48f,2.78f+b,0f,.16f,.35f,.14f,ORANGE);part(.48f,2.78f+b,0f,.16f,.35f,.14f,ORANGE);part(-.27f,2.13f+b,-.54f,.28f,.20f,.22f,MUZZLE);part(.27f,2.13f+b,-.54f,.28f,.20f,.22f,MUZZLE);part(0f,1.98f+b,-.77f,.12f,.06f,.03f,BLACK);tail(.72f,1.02f+b,.42f,ORANGE,s)}
        private fun patamon(b:Float,s:Float){base(b,GOLD,CREAM,CREAM);part(-.78f,2.25f+b,.04f,.40f,.22f,.16f,CREAM);part(.78f,2.25f+b,.04f,.40f,.22f,.16f,CREAM);part(-.52f,2.82f+b,0f,.15f,.34f,.15f,GOLD);part(.52f,2.82f+b,0f,.15f,.34f,.15f,GOLD);part(0f,2.05f+b,-.65f,.22f,.12f,.05f,MUZZLE);part(0f,2f+b,-.70f,.07f,.04f,.02f,BLACK)}
        private fun gatomon(b:Float,s:Float){base(b,CREAM,CREAM,CREAM);ears(WHITE,PINK,b,.49f);part(0f,2.03f+b,-.66f,.09f,.05f,.025f,PINK);part(0f,.83f+b,.66f,.20f,.18f,.65f,GOLD)}
        private fun tentomon(b:Float,s:Float){base(b,RED,RED,RED);part(-.72f,2.70f+b,0f,.17f,.48f,.17f,RED);part(.72f,2.70f+b,0f,.17f,.48f,.17f,RED);part(-.90f,1.02f+b,-.03f,.35f,.20f,.32f,BLUE);part(.90f,1.02f+b,-.03f,.35f,.20f,.32f,BLUE)}
        private fun gomamon(b:Float,s:Float){base(b,WHITE,WHITE,WHITE);ears(WHITE,PINK,b,.50f);part(0f,2.05f+b,-.66f,.13f,.08f,.03f,BLACK);for(x in listOf(-.48f,-.24f,0f,.24f,.48f))part(x,1.83f+b,.55f,.12f,.16f,.08f,WHITE);part(0f,1.10f+b,.56f,.60f,.78f,.20f,BLUE);tail(.88f,1.02f+b,.38f,BLUE,s)}
        private fun palmon(b:Float,s:Float){base(b,GREEN,PALE,PALE);for(x in listOf(-.50f,-.25f,0f,.25f,.50f))part(x,2.87f+b,0f,.13f,.36f,.11f,GREEN);part(0f,2.02f+b,-.65f,.11f,.06f,.03f,BLACK);part(0f,1.90f+b,.55f,.36f,.20f,.16f,PINK);part(0f,1.62f+b,.57f,.48f,.18f,.18f,PINK)}
        private fun biyomon(b:Float,s:Float){base(b,PINK,PEACH,CREAM);part(-.45f,2.83f+b,0f,.18f,.38f,.15f,PINK);part(.45f,2.83f+b,0f,.18f,.38f,.15f,PINK);part(0f,2.08f+b,-.65f,.20f,.11f,.04f,ORANGE);part(-.92f,1.18f+b,.10f,.32f,.68f,.18f,PINK);part(.92f,1.18f+b,.10f,.32f,.68f,.18f,PINK)}
        private fun veemon(b:Float,s:Float){base(b,VEEMON,VEEMON,CREAM);part(-.48f,2.87f+b,0f,.14f,.48f,.13f,VEEMON);part(.48f,2.87f+b,0f,.14f,.48f,.13f,VEEMON);part(-.25f,2.16f+b,-.56f,.30f,.18f,.20f,MUZZLE);part(.25f,2.16f+b,-.56f,.30f,.18f,.20f,MUZZLE);part(0f,2f+b,-.74f,.10f,.05f,.03f,BLACK)}
        private fun wormmon(b:Float,s:Float){base(b,GREEN,PALE,PALE);part(-.45f,2.86f+b,0f,.15f,.42f,.14f,GREEN);part(.45f,2.86f+b,0f,.15f,.42f,.14f,GREEN);part(0f,2.03f+b,-.66f,.11f,.06f,.03f,BLACK);part(0f,1.72f+b,.55f,.30f,.34f,.20f,GREEN)}
        private fun guilmon(b:Float,s:Float){base(b,CRIMSON,CREAM,CREAM);part(-.50f,2.83f+b,0f,.18f,.38f,.16f,CRIMSON);part(.50f,2.83f+b,0f,.18f,.38f,.16f,CRIMSON);part(-.27f,2.15f+b,-.55f,.29f,.19f,.22f,CREAM);part(.27f,2.15f+b,-.55f,.29f,.19f,.22f,CREAM);part(0f,2f+b,-.75f,.11f,.06f,.03f,BLACK);tail(0f,1.15f+b,.60f,CRIMSON,s)}
        private fun renamon(b:Float,s:Float){base(b,GOLDEN,CREAM,CREAM);part(-.42f,2.94f+b,0f,.12f,.57f,.12f,GOLDEN);part(.42f,2.94f+b,0f,.12f,.57f,.12f,GOLDEN);part(-.78f,2.64f+b,0f,.14f,.28f,.13f,GOLDEN);part(.78f,2.64f+b,0f,.14f,.28f,.13f,GOLDEN);part(0f,2.04f+b,-.66f,.09f,.05f,.025f,BLACK);part(-.88f,1.28f+b,.05f,.22f,.78f,.20f,GOLDEN);part(.88f,1.28f+b,.05f,.22f,.78f,.20f,GOLDEN);tail(.58f,1.05f+b,.52f,GOLDEN,s)}
        private fun part(x:Float,y:Float,z:Float,sx:Float,sy:Float,sz:Float,c:FloatArray){Matrix.setIdentityM(m,0);Matrix.multiplyMM(m,0,rot,0,m,0);Matrix.translateM(m,0,x,y,z);Matrix.scaleM(m,0,sx,sy,sz);Matrix.multiplyMM(mv,0,v,0,m,0);Matrix.multiplyMM(mv,0,p,0,mv,0);nm[0]=rot[0];nm[1]=rot[1];nm[2]=rot[2];nm[3]=rot[4];nm[4]=rot[5];nm[5]=rot[6];nm[6]=rot[8];nm[7]=rot[9];nm[8]=rot[10];mesh.draw(mv,nm,c[0],c[1],c[2])}
    }
    private class Mesh{
        private lateinit var vb:FloatBuffer;private lateinit var ib:ShortBuffer;private var prog=0;private var pos=0;private var mat=0;private var nmat=0;private var col=0;private var light=0
        init{val rings=20;val segs=32;val d=ArrayList<Float>();val q=ArrayList<Short>();for(a in 0..rings){val ph=Math.PI*a/rings;val y=cos(ph).toFloat();val rr=sin(ph).toFloat();for(b in 0 until segs){val th=2*Math.PI*b/segs;d+=(rr*cos(th)).toFloat();d+=y;d+=(rr*sin(th)).toFloat()}};for(a in 0 until rings)for(b in 0 until segs){val x=(a*segs+b).toShort();val y=(a*segs+(b+1)%segs).toShort();val z=((a+1)*segs+b).toShort();val w=((a+1)*segs+(b+1)%segs).toShort();q+=x;q+=z;q+=y;q+=y;q+=z;q+=w};vb=ByteBuffer.allocateDirect(d.size*4).order(ByteOrder.nativeOrder()).asFloatBuffer().apply{put(d.toFloatArray()).position(0)};ib=ByteBuffer.allocateDirect(q.size*2).order(ByteOrder.nativeOrder()).asShortBuffer().apply{put(q.toShortArray()).position(0)}}
        fun program(){val vs="attribute vec4 p;uniform mat4 m;uniform mat3 nmat;varying vec3 n;void main(){n=normalize(nmat*normalize(p.xyz));gl_Position=m*p;}";val fs="precision mediump float;uniform vec4 c;uniform vec3 light;varying vec3 n;void main(){vec3 nn=normalize(n);vec3 ll=normalize(light);float d=max(dot(nn,ll),0.0);float fill=max(dot(nn,normalize(vec3(.55,.35,.75))),0.0);float rim=pow(1.0-max(dot(nn,vec3(0.,0.,1.)),0.0),2.4);float spec=pow(max(dot(reflect(-ll,nn),vec3(0.,0.,1.)),0.0),28.);vec3 base=c.rgb*(.43+.47*d+.10*fill);base+=c.rgb*.10*rim;base+=vec3(1.)*.075*spec;gl_FragColor=vec4(base,c.a);}";val a=sh(GLES20.GL_VERTEX_SHADER,vs);val b=sh(GLES20.GL_FRAGMENT_SHADER,fs);prog=GLES20.glCreateProgram();GLES20.glAttachShader(prog,a);GLES20.glAttachShader(prog,b);GLES20.glLinkProgram(prog);pos=GLES20.glGetAttribLocation(prog,"p");mat=GLES20.glGetUniformLocation(prog,"m");nmat=GLES20.glGetUniformLocation(prog,"nmat");col=GLES20.glGetUniformLocation(prog,"c");light=GLES20.glGetUniformLocation(prog,"light")}
        private fun sh(t:Int,s:String)=GLES20.glCreateShader(t).also{GLES20.glShaderSource(it,s);GLES20.glCompileShader(it)}
        fun draw(m:FloatArray,n:FloatArray,r:Float,g:Float,b:Float){GLES20.glUseProgram(prog);GLES20.glEnableVertexAttribArray(pos);GLES20.glVertexAttribPointer(pos,3,GLES20.GL_FLOAT,false,12,vb);GLES20.glUniformMatrix4fv(mat,1,false,m,0);GLES20.glUniformMatrix3fv(nmat,1,false,n,0);GLES20.glUniform4f(col,r,g,b,1f);GLES20.glUniform3f(light,-.35f,.80f,-.75f);GLES20.glDrawElements(GLES20.GL_TRIANGLES,ib.capacity(),GLES20.GL_UNSIGNED_SHORT,ib);GLES20.glDisableVertexAttribArray(pos)}
    }
    companion object{private val BLUE=floatArrayOf(.055f,.34f,.58f);private val PELT=floatArrayOf(.91f,.89f,.80f);private val ORANGE=floatArrayOf(1f,.67f,.055f);private val CREAM=floatArrayOf(.94f,.83f,.63f);private val MUZZLE=floatArrayOf(.94f,.76f,.56f);private val GOLD=floatArrayOf(1f,.83f,.14f);private val YELLOW=floatArrayOf(1f,.72f,.07f);private val PINK=floatArrayOf(1f,.40f,.36f);private val BLACK=floatArrayOf(.012f,.012f,.016f);private val RED=floatArrayOf(.78f,.025f,.035f);private val WHITE=floatArrayOf(1f,1f,1f);private val STRIPE=floatArrayOf(.035f,.22f,.43f);private val CLAW=floatArrayOf(.72f,.025f,.025f);private val GREEN=floatArrayOf(.10f,.62f,.22f);private val PALE=floatArrayOf(.88f,.92f,.72f);private val PEACH=floatArrayOf(1f,.72f,.48f);private val VEEMON=floatArrayOf(.10f,.48f,.78f);private val CRIMSON=floatArrayOf(.72f,.05f,.07f);private val GOLDEN=floatArrayOf(.88f,.66f,.24f)}
}
